(()=>{'use strict';const lang=document.documentElement.lang,other=lang==='ar'?'en':'ar',language=document.querySelector('#language'),menu=document.querySelector('#menu'),nav=document.querySelector('#plans-nav');let current=location.hash.slice(1)||'hero',navigationUntil=location.hash?performance.now()+1000:0;function cleanLegacy(){if(location.hash==='#contact'){let url=new URL(location.href);url.hash='plans';url.searchParams.delete('plan');history.replaceState({},'',url);current='plans';document.querySelector('#plans').scrollIntoView({behavior:'instant'});}}function languageURL(){const url=new URL('../'+other+'/',location.href);url.search=location.search;url.hash=current;language.href=url.href;document.querySelector('#hint-link').href=url.href;}const cookie=(k,v)=>document.cookie=k+'='+v+';path=/;max-age=31536000;SameSite=Lax';const hasCookie=k=>document.cookie.split(';').some(x=>x.trim().startsWith(k+'='));cleanLegacy();languageURL();language.addEventListener('click',()=>cookie('lang',other));document.querySelector('#hint-link').addEventListener('click',()=>cookie('lang',other));if(navigator.language.slice(0,2)===other&&!hasCookie('lang_hint'))document.querySelector('#language-hint').hidden=false;document.querySelector('#hint-close').addEventListener('click',()=>{cookie('lang_hint','closed');document.querySelector('#language-hint').hidden=true;});const closeMenu=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');};menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open);});addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',closeMenu));addEventListener('hashchange',()=>{cleanLegacy();current=location.hash.slice(1)||current;navigationUntil=performance.now()+1000;languageURL();});if('IntersectionObserver'in window){const active=new IntersectionObserver(entries=>{for(const e of entries){if(e.isIntersecting&&performance.now()>navigationUntil){current=e.target.id;nav.querySelectorAll('a').forEach(a=>{if(a.hash==='#'+current)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});languageURL();}}},{rootMargin:'-100px 0px -30% 0px'});document.querySelectorAll('main section').forEach(s=>active.observe(s));}})();
